        0.0
    };
    score += need.powi(2) * (1.0 - t).powi(2);

    // 3. Bonus for sole fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - t);
    }

    // 4. Tight‑fit encouragement
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    let tightness = 1.0 - residual_ratio; // 0.0 .. 1.0
    score -= tightness * 15.0 * t.powf(1.5);

    // 5. Existing‑bin pressure
    score += (open_bins_count as f64) * t.powi(2);

    // 6. New‑bin penalty early, softened near end
