    // Penalise deviation from global mean residual
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * dev / mean_residual.max(1.0);

    // Extra penalty for bins that were already highly full
    if bin_residual > (bin_capacity * 8 / 10) {
        score += 1.5
            * ((bin_residual - (bin_capacity * 8 / 10)) as f64 / bin_capacity as f64);
    }

    // Look‑ahead: reward bins that can also accommodate the next item
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            score -= 1.0 * next_item_size as f64;
        } else {
            score += 0.6 * (next_item_size as f64 - post_residual as f64);
            if next_item_size > post_residual * 3 / 2 {
                score += 0.3 * (next_item_size as f64 - (post_residual as f64 * 1.5));
            }
        }
    }

    // Prefer existing bins when many are open
    score -= 0.02 * (open_bins_count as f64).powf(0.9);

