    if bin_residual == bin_capacity {
        let base = if fitting_bins_count <= 2 {
            9.0
        } else if fitting_bins_count <= 5 {
            6.0
        } else {
            4.0
        };
        score += base
            * (1.0 - progress).powi(2)
            * (1.0 + 0.1 * (open_bins_count as f64).sqrt());
    }

    // Huge bonus if this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0;
