pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Progress through the stream
    let progress = step_index as f64 / total_items as f64;

    // Ratio of residual to capacity after placing the item
    let residual_ratio = post_residual as f64 / bin_capacity as f64;

    // Target ratio based on the current mean residual
    let mean_ratio = mean_residual / bin_capacity as f64;

    let mut score = 0.0;

    // 1. Prefer a moderate residual – bell‑shaped term
    score += 10.0 * residual_ratio * (1.0 - residual_ratio);

    // 2. Penalise deviation from the current mean residual
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.4 * dev / mean_residual.max(1.0);

    // 3. Extra penalty if the bin was already very full before the item
    if bin_residual > bin_capacity * 7 / 10 {
        score += 3.0 * ((bin_residual - bin_capacity * 7 / 10) as f64);
    }

    // 4. Look‑ahead: favour bins that can also hold the next item
    if next_item_size > 0 {
        let next_ratio = next_item_size as f64 / bin_capacity as f64;
        if next_ratio <= residual_ratio {
            score -= 0.6 * next_item_size as f64;
        } else {
            score += 1.5 * (next_item_size - post_residual) as f64;
        }
        // Additional penalty if the next item is unusually large
        if next_item_size > (mean_residual * 1.4) as u32 {
            score += 1.0 * (next_item_size as f64 - mean_residual * 1.4);
        }
    }

    // 5. Mild penalty for many open bins, scaled by how crowded they are
    score += 0.015 * (open_bins_count as f64).powf(1.05);

    // 6. New‑bin candidate: heavier penalty early, lighter later
    if bin_residual == bin_capacity {
        let base = if fitting_bins_count > 2 { 7.5 } else { 3.5 };
        score += base * (1.0 - progress).powf(1.3) * (fitting_bins_count as f64).sqrt();
    }

    // 7. Strong reward if this is the sole fitting bin
    if fitting_bins_count == 1 {
        score -= 5.8;
    }

    // 8. Penalise dead‑space left after placement
    if residual_ratio > 0.8 {
        score += 4.0 * (residual_ratio - 0.8);
    }

