    if open_bins_count > 0 && fitting_bins_count < open_bins_count / 4 {
        score += 1.5 * (open_bins_count as f64 - (fitting_bins_count as f64 * 4.0));
    }

    // 10. Early‑stream encouragement to open a new bin if many bins are closed
    if progress < 0.2 && open_bins_count > 5 {
        score -= 2.0;
    }

