pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Progress in the stream
    let progress = step_index as f64 / total_items as f64;

    // Current and pre‑placement residual ratios
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    let pre_residual_ratio = bin_residual as f64 / bin_capacity as f64;

    // Base score: aim for a residual around 0.35
    let target = 0.35_f64;
    let base = 1.0_f64 + (residual_ratio - target).abs() * 5.0_f64;

    // Penalise bins that are too empty before placement
    let pre_pen = if pre_residual_ratio > 0.8_f64 {
        (pre_residual_ratio - 0.8_f64).powi(2) * 20.0_f64
    } else {
        0.0_f64
    };

    // Deviation from the average residual
    let dev = (post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0_f64);
    let mean_pen = 0.2_f64 * dev;

    // More fitting bins → lower score
    let fit_pen = 0.1_f64 * (fitting_bins_count as f64).ln().max(0.0_f64);

    // Encourage reuse when many bins are open (lower score)
    let reuse_rev = -0.01_f64 * (open_bins_count as f64).powf(0.9_f64);

    // Look‑ahead adjustment
    let lookahead = if next_item_size > 0 {
        if next_item_size <= post_residual {
            -0.3_f64 * next_item_size as f64
        } else {
            0.5_f64 * (next_item_size - post_residual) as f64
        }
    } else {
        0.0_f64
    };

    // New‑bin candidate penalty that relaxes over time
    let new_bin_pen = if bin_residual == bin_capacity {
        let base = if fitting_bins_count > 2 { 6.0_f64 } else { 4.0_f64 };
        base * (1.0_f64 - progress).powf(1.4_f64)
    } else {
        0.0_f64
    };

    // Optional bonus if the next item will fit in the same bin after placement
    let future_overflow_pen = if next_item_size > 0
        && next_item_size > post_residual
        && next_item_size <= bin_residual
    {
        -0.2_f64 * next_item_size as f64
    } else {
        0.0_f64
    };

    // Aggregate score
    let mut score = base
        + pre_pen
        + mean_pen
        + fit_pen
        + reuse_rev
        + lookahead
        + new_bin_pen
        + future_overflow_pen;

    // Strong reward for the unique fitting bin
    if fitting_bins_count == 1 {
        score -= 4.0_f64;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Progress factor (0.0 .. 1.0)
    let progress = step_index as f64 / total_items as f64;

    // Residuals and ratios
    let cap_f = bin_capacity as f64;
    let before_f = bin_residual as f64;
    let after_f  = post_residual as f64;
    let ratio_before = before_f / cap_f;
    let ratio_after  = after_f / cap_f;

    // Base score: prefer bins that are almost full after placement
    let mut score = 3.0 * (1.0 - ratio_after);

    // Penalise deviation from the global mean residual
    let dev = (after_f - mean_residual).abs();
    score += 0.5 * dev / mean_residual.max(1.0);

    // Heavy penalty if the bin was already >90 % full
    if ratio_before > 0.9 {
        let excess = before_f - 0.9 * cap_f;
        score += 2.0 * (excess / cap_f);
    }

    // Look‑ahead: evaluate the fit of the next item in this bin
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        let next_fit = next_f <= after_f;
        let next_res_after = if next_fit { after_f - next_f } else { after_f };
        let next_ratio_after = next_res_after / cap_f;

        // Reward a good fit for the next item, penalise a bad one
        if next_fit {
            score -= 1.5 * (1.0 - next_ratio_after);
        } else {
            score += 1.2 * (1.0 - next_ratio_after);
        }
    }

    // Slight penalty for many open bins (prefer to reuse)
    score += 0.015 * (open_bins_count as f64).ln().max(0.0);

    // New‑bin consideration: a logistic‑shaped bonus that decays with progress
    if bin_residual == bin_capacity {
        // Base penalty inversely proportional to the number of open bins
        let base = if fitting_bins_count > 4 { 7.0 } else { 4.0 };
        let logistic = 1.0 / (1.0 + (progress * 5.0).exp());
        score += base * logistic;
    }

    // If this is the only bin that can fit the item, large bonus
    if fitting_bins_count == 1 {
        score -= 5.5;
    }

    // Bonus when the final residual is close to the global mean
    if (after_f - mean_residual).abs() <= 0.03 * cap_f {
        score -= 1.2;
    }

    // Bonus for almost full bins (residual < 5 % of capacity)
    if ratio_after < 0.05 {
        score -= 0.3;
    }

    // Additional penalty for opening a new bin when many are already open
    if bin_residual == bin_capacity && open_bins_count > 10 {
        score += 1.0;
    }

    score
}
